import { spawnSync } from 'node:child_process';
import { createRequire } from 'node:module';
import { readFileSync, lstatSync, existsSync, unlinkSync, realpathSync } from 'node:fs';
import { resolve, dirname, relative, sep } from 'node:path';
const root = process.cwd();
const mode = process.argv[2];
const apps = [['backoffice','@yuta/backoffice'],['web','@yuta/web'],['booking-web','@yuta/booking-web'],['feedback-web','@yuta/feedback-web'],['yuta-pos','@yuta/pos'],['yuta-display','@yuta/display']];
const outputs=['next-env.d.ts','.next/types/routes.d.ts','.next/types/validator.ts','.next/types/cache-life.d.ts'];
function outputPath(app,p) {
 const base=resolve(root,'apps',app); const dest=resolve(base,p);
 if(!dest.startsWith(base+sep))throw Error('Outside app');
 for(let dir=dirname(dest);dir!==base;dir=dirname(dir))if(existsSync(dir)&&lstatSync(dir).isSymbolicLink())throw Error('Linked output parent');
 if(existsSync(dest)&&!lstatSync(dest).isFile())throw Error('Non-file output');
 return dest;
}
function validate(app,req) {
 const ts=req('typescript');
 const trees=outputs.map(p=>{
  const file=outputPath(app,p),text=readFileSync(file,'utf8');
  if(!text.trim())throw Error('Empty output: '+p);
  const tree=ts.createSourceFile(p,text,ts.ScriptTarget.Latest,true);
  if(tree.parseDiagnostics.length)throw Error('Invalid TypeScript output: '+p);
  return tree;
 });
 const imports=t=>t.statements.filter(ts.isImportDeclaration).map(n=>n.moduleSpecifier.text);
 if(!trees[0].typeReferenceDirectives.some(r=>r.fileName==='next')||!trees[0].typeReferenceDirectives.some(r=>r.fileName==='next/image-types/global')||!imports(trees[0]).includes('./.next/types/routes.d.ts'))throw Error('Invalid next-env references');
 if(!trees[1].statements.some(n=>ts.isTypeAliasDeclaration(n)&&n.name.text==='AppRoutes')||!trees[1].statements.some(n=>ts.isInterfaceDeclaration(n)&&n.name.text==='ParamMap'))throw Error('Invalid route declarations');
 if(!imports(trees[2]).includes('./routes.js')||!trees[2].statements.some(n=>ts.isTypeAliasDeclaration(n)&&n.name.text==='AppPageConfig'))throw Error('Invalid validator');
 if(!trees[3].statements.some(n=>ts.isModuleDeclaration(n)&&n.name.text==='next/cache'))throw Error('Invalid cache declarations');
}
try {
 for(const [app,name] of apps){
  const appRoot=resolve(root,'apps',app),req=createRequire(resolve(appRoot,'package.json'));
  if(JSON.parse(readFileSync(resolve(appRoot,'package.json'))).name!==name)throw Error('Package mismatch');
  if(req('next/package.json').version!=='16.2.9')throw Error('Unreviewed Next version');
  if(mode==='validated')for(const p of outputs){const f=outputPath(app,p);if(existsSync(f))unlinkSync(f);}
  const args=[...(mode==='raw'?[]:['--unhandled-rejections=strict']),req.resolve('next/dist/bin/next'),'typegen'];
  console.log('GENERATOR_START '+app);
  const result=spawnSync(process.execPath,args,{cwd:appRoot,env:process.env,stdio:'inherit',timeout:120000,shell:false});
  console.log('GENERATOR_EXIT '+JSON.stringify({app,status:result.status,signal:result.signal,error:result.error?.message}));
  if(result.error||result.signal||result.status!==0)throw Error('Generator failed: '+app);
  // Experimental post-process invalid-result injection only; never a proposed production switch.
  if(mode==='validated'&&process.env.PROBE_INVALID_RESULT===app)unlinkSync(outputPath(app,'.next/types/routes.d.ts'));
  if(mode==='validated')validate(app,req);
  console.log('GENERATOR_ACCEPTED '+app);
 }
 console.log('BOOTSTRAP_SUCCESS');
} catch(error){console.error('BOOTSTRAP_REJECTED '+error.message);process.exitCode=1;}

